const $ = (s, root=document) => root.querySelector(s);
const esc = v => String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon = n => (ICONS[n] || ICONS['grid']).replace('<svg ', '<svg aria-hidden="true" focusable="false" ');
const money = n => new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n);
const groups = [
 {id:'apartment',name:'Apartment',icon:'home',tone:'',members:4,balance:310,power:1240,available:1116.84,total:486.2,budget:1200,period:'Every month'},
 {id:'weekend',name:'Weekend crew',icon:'coffee',tone:'warm',members:4,balance:156.12,power:624.5,available:470.3,total:218.4,budget:800,period:'Every 2 weeks'},
 {id:'roadtrip',name:'Road trip',icon:'truck',tone:'purple',members:3,balance:160,power:480,available:480,total:138,budget:900,period:'Every month'}
];
const pending = [
 {id:'juniper',name:'Juniper dinner',merchant:'Juniper',share:38.55,total:154.2,group:'weekend',icon:'coffee',date:'Today, 7:42 PM'},
 {id:'wholefoods',name:'Whole Foods',merchant:'Whole Foods',share:24.80,total:99.20,group:'apartment',icon:'shopping-bag',date:'Today, 12:18 PM'},
 {id:'spotify',name:'Spotify',merchant:'Spotify',share:5.99,total:23.96,group:'apartment',icon:'music',date:'Yesterday'}
];
